package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed production-equivalent completion composition without calibration or selection. */
final class BuyReplacementQuantityRoundTripCompletionEvaluator {
 BuyReplacementQuantityRoundTripCompletionEvaluationSet evaluate(BuyReplacementQuantityFillViabilityAssessment s,long at){if(s==null||s.getOutcome()!=BuyReplacementQuantityFillViabilityOutcome.VIABLE||at<s.getAssessedAt()||s.getAssessedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||s.getViableCandidates()==null||s.getViableCandidates().isEmpty())return null;List<BuyReplacementQuantityRoundTripCompletionEvaluation> out=new ArrayList<>(s.getViableCandidates().size());int completeIndex=0;for(BuyReplacementQuantityFillViableCandidate v:s.getViableCandidates()){while(completeIndex<s.getEvaluations().size()&&!matches(v,s.getEvaluations().get(completeIndex)))completeIndex++;if(completeIndex>=s.getEvaluations().size()||!valid(v,s))return null;double p=v.getBuyProbability()*v.getSellProbability();if(!Double.isFinite(p)||p<=0||p>1)return null;out.add(new BuyReplacementQuantityRoundTripCompletionEvaluation(v,p));completeIndex++;}return new BuyReplacementQuantityRoundTripCompletionEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementQuantityFillViableCandidate v,BuyReplacementQuantityFillViabilityAssessment s){return v!=null&&v.getFillableQuantity()==s.getExactRemainderQuantity()&&v.getQuantity()>0&&v.getQuantity()<=v.getFillableQuantity()&&v.getBuyPrice()>0&&v.getSellPrice()>v.getBuyPrice()&&v.getSizeGridIndex()>=0&&Double.isFinite(v.getSizeShare())&&v.getSizeShare()>0&&Double.isFinite(v.getKellyFraction())&&v.getKellyFraction()>0&&Double.isFinite(v.getBuyProbability())&&v.getBuyProbability()>0&&v.getBuyProbability()<=1&&Double.isFinite(v.getSellProbability())&&v.getSellProbability()>0&&v.getSellProbability()<=1&&Double.isFinite(v.getBuyExpectedHours())&&v.getBuyExpectedHours()>=0&&Double.isFinite(v.getSellExpectedHours())&&v.getSellExpectedHours()>=0&&Double.isFinite(v.getBuyUnitsPerHour())&&v.getBuyUnitsPerHour()>=0&&Double.isFinite(v.getSellUnitsPerHour())&&v.getSellUnitsPerHour()>=0&&!Double.isNaN(v.getBuyWaitHours())&&v.getBuyWaitHours()>=0&&!Double.isNaN(v.getSellWaitHours())&&v.getSellWaitHours()>=0;}
 private static boolean matches(BuyReplacementQuantityFillViableCandidate v,BuyReplacementQuantityFillEvaluation e){return v!=null&&e!=null&&v.getBuyOffsetIndex()==e.getBuyOffsetIndex()&&v.getSellOffsetIndex()==e.getSellOffsetIndex()&&v.getBuyPrice()==e.getBuyPrice()&&v.getSellPrice()==e.getSellPrice()&&v.getFillableQuantity()==e.getFillableQuantity()&&v.getQuantity()==e.getQuantity()&&v.getSizeGridIndex()==e.getSizeGridIndex()&&Double.compare(v.getSizeShare(),e.getSizeShare())==0&&Double.compare(v.getKellyFraction(),e.getKellyFraction())==0&&Double.compare(v.getExpectedProfit(),e.getExpectedProfit())==0&&v.getWorstLoss()==e.getWorstLoss()&&Double.compare(v.getBuyProbability(),e.getBuyProbability())==0&&Double.compare(v.getBuyExpectedHours(),e.getBuyExpectedHours())==0&&Double.compare(v.getBuyUnitsPerHour(),e.getBuyUnitsPerHour())==0&&Double.compare(v.getBuyWaitHours(),e.getBuyWaitHours())==0&&Double.compare(v.getSellProbability(),e.getSellProbability())==0&&Double.compare(v.getSellExpectedHours(),e.getSellExpectedHours())==0&&Double.compare(v.getSellUnitsPerHour(),e.getSellUnitsPerHour())==0&&Double.compare(v.getSellWaitHours(),e.getSellWaitHours())==0;}
}
